"use strict";(globalThis.webpackChunkgrc||=[]).push([[18224],{58545(e){e.exports=JSON.parse('{"citeKey":"jin2010checkpointingperformance","slug":"jin-2010-checkpointing-performance-beac","title":"Checkpointing Orchestration for Performance Improvement","authors":["H. Jin"],"venue":"40th Annual IEEE/IFIP International Conference on Dependable Systems and Networks (DSN 2010), Student Paper","type":"WIP","entryType":"inproceedings","date":"2010","year":2010,"era":"iit","abstract":"Checkpointing is a mostly used mechanism for supporting fault tolerance of high performance computing (HPC), but notorious in its expensive disk access. Parallel file systems such as Lustre, GPFS, PVFS are widely deployed on super computers to provide fast I/O bandwidth for general data-intensive applications. However, the unique feature of checkpointing makes it impossible to benefit from the parallel file systems. In addition, the design of parallel file system introduces extra contention overhead for checkpointing and significantly degrades the performance. In this study, we propose checkpointing orchestration to mask the unnecessary overhead for a better performance. We extend Open MPI and PVFS to support the idea of checkpointing orchestration. The experimental results confirm the potential of the proposed checkpointing orchestration.","hasAbstract":true,"lede":"In this study, we propose checkpointing orchestration to mask the unnecessary overhead for a better performance.","links":{"pdf":"https://grc.iit.edu/papers/2010/jin-2010-checkpointing-performance-beac.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":["fence"],"memberAuthors":[]}')}}]);